N = 45

def coloring(x, y, z):
    # Using 0-based indexing: 0 <= x, y, z < N
    return (x + y + z) % 2

def check_orientation(fixed_coord_idx, fixed_coord_val):
    """
    Checks the set of colors for slices fixed along the dimension specified by fixed_coord_idx.
    fixed_coord_idx: 0=X, 1=Y, 2=Z
    fixed_coord_val: The coordinate value (0 to N-1)
    """
    colors_found = set()

    if fixed_coord_idx == 0: # Fixed X, checking YZ plane
        x0 = fixed_coord_val
        for y in range(N):
            for z in range(N):
                colors_found.add(coloring(x0, y, z))
    elif fixed_coord_idx == 1: # Fixed Y, checking XZ plane
        y0 = fixed_coord_val
        for x in range(N):
            for z in range(N):
                colors_found.add(coloring(x, y0, z))
    elif fixed_coord_idx == 2: # Fixed Z, checking XY plane
        z0 = fixed_coord_val
        for x in range(N):
            for y in range(N):
                colors_found.add(coloring(x, y, z0))

    return colors_found

# Check all slices for Orientation Z (XY plane, fixed Z)
print("--- Checking Z slices ---")
all_z_ok = True
for z0 in range(N):
    s_z = check_orientation(2, z0)
    if s_z != {0, 1}:
        print(f"Failure at Z={z0}: Colors found {s_z}")
        all_z_ok = False
    else:
        # print(f"Success at Z={z0}: Colors found {s_z}")
        pass
if all_z_ok:
    print("All Z slices contain {0, 1}. Z orientation verified.")

# Check all slices for Orientation Y (XZ plane, fixed Y)
print("\n--- Checking Y slices ---")
all_y_ok = True
for y0 in range(N):
    s_y = check_orientation(1, y0)
    if s_y != {0, 1}:
        print(f"Failure at Y={y0}: Colors found {s_y}")
        all_y_ok = False
    else:
        # print(f"Success at Y={y0}: Colors found {s_y}")
        pass
if all_y_ok:
    print("All Y slices contain {0, 1}. Y orientation verified.")

# Check all slices for Orientation X (YZ plane, fixed X)
print("\n--- Checking X slices ---")
all_x_ok = True
for x0 in range(N):
    s_x = check_orientation(0, x0)
    if s_x != {0, 1}:
        print(f"Failure at X={x0}: Colors found {s_x}")
        all_x_ok = False
    else:
        # print(f"Success at X={x0}: Colors found {s_x}")
        pass
if all_x_ok:
    print("All X slices contain {0, 1}. X orientation verified.")

print("\n--- Overall Conclusion ---")
if all_z_ok and all_y_ok and all_x_ok:
